import Foundation
import CoreLocation
final class LocationTracker:NSObject,CLLocationManagerDelegate {
 static let shared=LocationTracker()
 let manager=CLLocationManager();var pendingStart:((Error?)->Void)?;var lastSent=Date.distantPast;var sending=false
 override init(){super.init();manager.delegate=self;manager.desiredAccuracy=kCLLocationAccuracyBest;manager.distanceFilter=kCLDistanceFilterNone;manager.activityType = .fitness;manager.pausesLocationUpdatesAutomatically=false;manager.allowsBackgroundLocationUpdates=true;manager.showsBackgroundLocationIndicator=true}
 func start(_ completion:@escaping(Error?)->Void){guard SessionVault.shared.session() != nil else{completion(NSError(domain:"Előbb jelentkezz be",code:401));return};pendingStart=completion;switch manager.authorizationStatus{case .authorizedAlways:activate();case .notDetermined:manager.requestWhenInUseAuthorization();case .authorizedWhenInUse:manager.requestAlwaysAuthorization();completion(NSError(domain:"A folyamatos háttérmegosztáshoz válaszd a Mindig helyengedélyt a telefon Beállításaiban",code:403));pendingStart=nil;default:completion(NSError(domain:"A helymeghatározás engedélye szükséges",code:403));pendingStart=nil}}
 func activate(){SessionVault.shared.sharing=true;manager.startUpdatingLocation();manager.startMonitoringSignificantLocationChanges();pendingStart?(nil);pendingStart=nil}
 func resumeRequested(){if SessionVault.shared.sharing&&SessionVault.shared.session() != nil&&manager.authorizationStatus == .authorizedAlways{activate()}}
 func stop(){SessionVault.shared.sharing=false;manager.stopUpdatingLocation();manager.stopMonitoringSignificantLocationChanges();pendingStart?(NSError(domain:"A megosztás indítását leállítottad",code:499));pendingStart=nil;Backend.shared.request("/functions/v1/game-api","{\"action\":\"stop\"}"){_,_ in}}
 func locationManagerDidChangeAuthorization(_ manager:CLLocationManager){if manager.authorizationStatus == .authorizedAlways{if pendingStart != nil||SessionVault.shared.sharing{activate()}}else if manager.authorizationStatus == .authorizedWhenInUse&&pendingStart != nil{manager.requestAlwaysAuthorization();pendingStart?(NSError(domain:"A háttérmegosztáshoz Mindig helyengedély kell. Ha a rendszer nem ajánlja fel, állítsd be a telefon Beállításaiban, majd indítsd újra a megosztást",code:403));pendingStart=nil}else if manager.authorizationStatus == .denied||manager.authorizationStatus == .restricted{stop()}}
 func locationManager(_ manager:CLLocationManager,didUpdateLocations locations:[CLLocation]){guard SessionVault.shared.sharing,let point=locations.last,point.horizontalAccuracy>=0,point.horizontalAccuracy<=50,abs(point.timestamp.timeIntervalSinceNow)<=30,Date().timeIntervalSince(lastSent)>=10,!sending else{return};lastSent=Date();sending=true;do{let body=try Backend.shared.json(["action":"location","data":["lat":point.coordinate.latitude,"lng":point.coordinate.longitude,"accuracy":point.horizontalAccuracy,"background":true]]);Backend.shared.request("/functions/v1/game-api",body){_,_ in DispatchQueue.main.async{self.sending=false}}}catch{sending=false}}
 func locationManager(_ manager:CLLocationManager,didFailWithError error:Error){if (error as NSError).code==CLError.denied.rawValue{stop()}}
}
